# Let me look at the JSON structure more comprehensively
import json

d = json.load(open('/app/resources/treasury_bulletin_1947_02.json'))

# Check if there's any additional data in the JSON that wasn't in the text
# Let's look at the full structure of elements that might contain yield data
for i, elem in enumerate(d['document']['elements']):
    if isinstance(elem, dict):
        text = str(elem.get('text', ''))
        if 'High-grade' in text or 'corporate' in text:
            if '1938' in text or '1937' in text:
                print(f"Element {i}: {text[:200]}")

# Also check if there are any tables with different structures
print("\n\n=== Checking all tables in elements ===")
table_count = 0
for i, elem in enumerate(d['document']['elements']):
    if isinstance(elem, dict):
        if elem.get('type') == 'table' or 'table' in str(elem.get('class', '')):
            table_count += 1

print(f"Found {table_count} table elements")
EOF

python3 << 'EOF'
# Let me search through ALL elements in the JSON for ANY yield data
import json
d = json.load(open('/app/resources/treasury_bulletin_1947_02.json'))

# Search through ALL elements for anything containing yield data
found_data = []
for i, elem in enumerate(d['document']['elements']):
    if isinstance(elem, dict):
        text = str(elem.get('text', ''))
        if '1938' in text and ('yield' in text.lower() or 'bond' in text.lower()):
            found_data.append((i, text[:500]))

if found_data:
    print("Found yield data for 1938:")
    for i, text in found_data:
        print(f"Element {i}: {text}")
else:
    print("NO yield data for 1938 found in the JSON elements")

# Also check pages - maybe there's more data stored differently
print("\n\nChecking all page content...")
for i, page in enumerate(d['document']['pages']):
    if page.get('id') in [86, 87, 88, 89, 90]:
        print(f"Page {i} (id={page.get('id')}): {page}")
